  "anomalies": [
    {
      "category": "other",
      "components": ["U6"],
      "pins": ["U6.3", "U6.5"],
      "nets": ["GND", "+3.3V", "I2C1_SCL_NAVC", "I2C1_SDA_NAVC"],
      "observed": "TMP100 address pin ADD1 (pin 3) is tied to GND and ADD0 (pin 5) to +3.3V. For a TMP100, this selects I2C address 0x49, not the 0x4E stated in the schematic and specification.",
      "expected": "The sensor's configured address must match the documented and software-used address; to use 0x4E, use a compatible device/addressing scheme, or update the intended address and software to 0x49.",
      "evidence": [
        {
          "source": "schematic",
          "quote": "U6 TMP100; ADD0 pin 5 connected to +3.3V; ADD1 pin 3 connected to GND; “I2C address: 0x4E” (NAVC Peripherals, page 6)"
        },
        {
          "source": "spec",
          "quote": "Temperature sensor | TMP100, I2C addr 0x4E (Component Table, §2)"
        }
      ],
      "impact": "If firmware follows the documented 0x4E address, it will not find the temperature sensor; the hardware address selected by the pin straps is 0x49.",
      "confidence": 0.94
    }
  ],
  "summary": "The TMP100's address straps select 0x49, while both the schematic annotation and specification state 0x4E. Firmware using the documented address would fail to communicate with the sensor."
}

